CREATE SCHEMA publication_target_sql;
CREATE TABLE publication_parent_sql(id integer PRIMARY KEY, extra integer);
CREATE TABLE publication_child_sql(id integer REFERENCES publication_parent_sql(id));
CREATE SEQUENCE publication_owned_sql OWNED BY publication_parent_sql.extra;
CREATE INDEX publication_key_sql ON publication_parent_sql(extra) INCLUDE(id);
COMMENT ON TABLE publication_parent_sql IS 'published table';
COMMENT ON INDEX publication_key_sql IS 'published index';
COMMENT ON SEQUENCE publication_owned_sql IS 'published sequence';
INSERT INTO publication_parent_sql VALUES (1, 10);
INSERT INTO publication_child_sql VALUES (1);
BEGIN;
ALTER SEQUENCE publication_owned_sql INCREMENT BY 2;
ALTER TABLE publication_parent_sql RENAME TO publication_renamed_sql;
ALTER TABLE publication_renamed_sql SET SCHEMA publication_target_sql;
UPDATE publication_child_sql SET id = id;
SELECT nextval('publication_target_sql.publication_owned_sql');
ALTER TABLE publication_target_sql.publication_renamed_sql RENAME COLUMN extra TO amount;
CREATE INDEX publication_private_key_sql ON publication_target_sql.publication_renamed_sql(amount);
COMMIT;
SELECT id, amount FROM publication_target_sql.publication_renamed_sql WHERE amount = 10;
SELECT count(*) FROM publication_child_sql;
SELECT count(*) FROM pg_indexes WHERE schemaname = 'publication_target_sql' AND tablename = 'publication_renamed_sql';
SELECT obj_description('publication_target_sql.publication_renamed_sql'::regclass);
SELECT obj_description('publication_target_sql.publication_key_sql'::regclass);
SELECT obj_description('publication_target_sql.publication_owned_sql'::regclass);
SELECT nextval('publication_target_sql.publication_owned_sql');
BEGIN;
ALTER TABLE publication_target_sql.publication_renamed_sql RENAME TO publication_rolled_back_sql;
ALTER TABLE publication_target_sql.publication_rolled_back_sql RENAME TO publication_rolled_back_twice_sql;
SELECT nextval('publication_target_sql.publication_owned_sql');
ROLLBACK;
SELECT nextval('publication_target_sql.publication_owned_sql');
INSERT INTO publication_target_sql.publication_renamed_sql VALUES (2, 20);
INSERT INTO publication_child_sql VALUES (2);
SELECT count(*), sum(amount) FROM publication_target_sql.publication_renamed_sql;
SELECT count(*) FROM publication_child_sql;
